/**
 * 사용할 디자인 시스템 결정 (발행본 목록 → 단일 선택).
 * - systemName 지정 → 해당 이름 (미존재 시 가용 목록과 함께 NOT_FOUND)
 * - 미지정 → 1개면 그것, 0개=NOT_FOUND, 2개 이상=MULTIPLE(이름 지정 안내)
 * notFoundMessage 는 호스트별 안내 문구 주입점 (기본=웹 admin 탭 안내, 킷은 자체 문구).
 */
export function resolveFromList(
  systems: DesignSystemMeta[],
  systemName?: string,
  notFoundMessage: string = NOT_FOUND_MSG,
): ResolveResult {
  if (systemName) {
    const wanted = systemName.trim().toLowerCase();
    const hit = systems.find((s) => s.name === wanted);
    if (hit) return { ok: true, system: hit };
    return {
      ok: false,
      reason: 'not_found',
      candidates: systems.map((s) => s.name),
      message:
        systems.length > 0
          ? `"${systemName}" 이름의 발행된 디자인 시스템이 없습니다. 가용: ${systems.map((s) => s.name).join(', ')}`
          : notFoundMessage,
    };
  }

  if (systems.length === 0) return { ok: false, reason: 'not_found', message: notFoundMessage };
  if (systems.length === 1) return { ok: true, system: systems[0] };
  return {
    ok: false,
    reason: 'multiple',
    candidates: systems.map((s) => s.name),
    message:
      `발행된 디자인 시스템이 ${systems.length}개입니다(${systems.map((s) => s.name).join(', ')}). ` +
      'system 인자로 이름을 지정하세요. 사용자가 어느 시스템을 쓸지 말하지 않았다면 임의로 고르지 말고 먼저 사용자에게 질문한 뒤 진행하세요.',
  };
}

