/* ── 배송 규약 (파일로 저장 vs 패키지를 설치) ────────────────────────── */

/**
 * 소비 앱에 이미 있다고 보는 것 — 설치 지시에서 뺀다.
 * `next/*`·`react-dom/*` 같은 서브패스는 뿌리 이름으로 접힌 뒤 걸러진다.
 */
const AMBIENT_PACKAGES = new Set(['react', 'react-dom', 'next']);

/** npm 패키지 이름 규약. 서브패스를 자른 뿌리 이름만 통과시킨다. */
const NPM_NAME_RE = /^(?:@[a-z0-9][\w.-]*\/)?[a-z0-9][\w.-]*$/;

/** import·require 대상에서 패키지 뿌리 이름을 뽑는다. 상대경로는 버린다. */
function packageRootOf(spec: string): string | null {
  if (!spec || spec.startsWith('.') || spec.startsWith('/')) return null;
  const seg = spec.split('/');
  const root = spec.startsWith('@') ? seg.slice(0, 2).join('/') : seg[0];
  if (!root || root.length > 214 || !NPM_NAME_RE.test(root)) return null;
  return root;
}

/**
 * 코드가 실제로 가져다 쓰는 외부 패키지 목록.
 *
 * 선언이 아니라 코드에서 도출한다 — 둘을 따로 두면 어긋나는 날이 오고,
 * 그때 틀리는 쪽은 항상 안내 문구다. 코드가 진실의 원천이다.
 */
export function externalImports(code: string): string[] {
  const found = new Set<string>();
  const add = (spec: string | undefined) => {
    if (!spec) return;
    const root = packageRootOf(spec);
    if (root && !AMBIENT_PACKAGES.has(root)) found.add(root);
  };
  for (const m of code.matchAll(/\bfrom\s*['"]([^'"]+)['"]/g)) add(m[1]);
  for (const m of code.matchAll(/\bimport\s*\(\s*['"]([^'"]+)['"]\s*\)/g)) add(m[1]);
  for (const m of code.matchAll(/\brequire\s*\(\s*['"]([^'"]+)['"]\s*\)/g)) add(m[1]);
  // `import 'x'` 부수효과 형태 (from 절이 없다)
  for (const m of code.matchAll(/\bimport\s+['"]([^'"]+)['"]/g)) add(m[1]);
  return [...found].sort();
}

export type DesignDelivery =
  | { mode: 'save'; savePath: string; instruction: string; /** 저장 코드가 import 하는 외부 패키지 — 함께 설치 */ dependencies?: string[] }
  | { mode: 'install'; packages: string[]; instruction: string };

/** 코드가 컴포넌트를 **정의**하는가(저장할 파일) — 아니면 패키지 사용 **예제**(스니펫) */
export function definesComponent(code: string): boolean {
  return /\bexport\s+default\b/.test(code) || /\bexport\s+(?:async\s+)?(?:function|const|class)\s+[A-Z]/.test(code);
}

/**
 * 이 컴포넌트를 소비 앱에 어떻게 들이는가.
 *
 * 구현이 패키지에 있는 컴포넌트의 `#### Code` 는 **저장할 파일이 아니라 사용 예제**다(PDS —
 * Button 을 패키지에서 import 하는 줄 뒤에 JSX 만 있고 export 가 없다). 그걸
 * `components/design/Button.tsx` 로 저장하면 예제 조각이 그 이름으로 앉고 패키지는 설치되지 않는다.
 *
 * 반대로 코드가 컴포넌트를 **정의**하면(export default …) 외부 패키지를 import 하더라도 저장할
 * 파일이다 — `lucide-react` 아이콘·`clsx` 를 쓰는 관리자 작성 컴포넌트가 그렇다. 2026-08-28 리뷰:
 * "외부 import = install" 로만 판정하면 이런 컴포넌트가 어디에도 저장되지 않고 AI 가
 * `npm install lucide-react` 뒤 그 패키지에서 없는 이름을 import 했다. 그래서 판정 축은
 * **import 유무가 아니라 정의 유무**고, 저장형의 외부 패키지는 `dependencies` 로 같이 안내한다.
 */
export function componentDelivery(
  item: Pick<DesignItemFull, 'name' | 'codeLang'> & { code?: string | null },
): DesignDelivery {
  const code = item.code ?? '';
  const packages = code ? externalImports(code) : [];
  if (packages.length === 0 || definesComponent(code)) {
    const savePath = componentSavePath(item);
    const deps = packages.length > 0 ? ` 이 코드는 \`npm install ${packages.join(' ')}\` 이 필요합니다(package.json 에 이미 있으면 생략).` : '';
    return {
      mode: 'save',
      savePath,
      ...(packages.length > 0 && { dependencies: packages }),
      instruction: `${savePath} 에 코드를 수정 없이 그대로 저장하세요. 이미 이 파일이 있으면 첫 줄 \`// @design-system … hash:\` 를 아래 코드 첫 줄과 비교 — 같으면 재저장하지 말고 import 만, 다르거나 헤더가 없으면 아래 코드로 통째로 덮어쓰세요(발행본 갱신 반영).${deps}`,
    };
  }
  const list = packages.join(' ');
  return {
    mode: 'install',
    packages,
    instruction:
      `이 컴포넌트는 패키지로 제공됩니다 — 코드를 파일로 저장하지 마세요(아래 코드는 사용 예제입니다). ` +
      `\`npm install ${list}\` 로 설치하고(package.json 에 이미 있으면 생략), 예제처럼 import 해서 쓰세요. ` +
      `구현을 복사하거나 다시 만들지 마세요.`,
  };
}

