const sortedEntries = (obj: Record<string, string>): Array<[string, string]> =>
  Object.entries(obj).sort(([a], [b]) => a.localeCompare(b, 'en-US'));

const sortedCategories = (map: DesignTokenMap): Array<[string, Record<string, string>]> =>
  Object.entries(map).sort(([a], [b]) => a.localeCompare(b, 'en-US'));

/**
 * `:root { --{category}-{key}: value }` + `[data-theme="dark"] { ... }` — 키 정렬 고정(결정성).
 *
 * 다크 셀렉터는 `data-theme` 속성이다. 예전엔 `.dark` 클래스였는데, 그러면 이 CSS 를 받는
 * 세 소비처 — Sandpack 미리보기 토글(data-theme 관찰) · 생성 앱 프롬프트("html[data-theme='dark']
 * 로 구현") · PDS 패키지 tokens.css([data-theme="dark"]) — 가 전부 다른 스위치를 켜서 다크
 * 오버라이드가 영영 적용되지 않았다. 스펙이 이걸 "알려진 한계(v1)" 로 적어 두고 있었다.
 */
/** compat 이 강등 컴포넌트 문서에 삽입하는 IA 마커 — 표시/배포 본문에선 제거 (designCompat 과 쌍) */
export const COMPONENT_DOC_MARKER = '<!-- design-md: component-doc -->';
export const stripComponentDocMarker = (md: string): string => md.split(COMPONENT_DOC_MARKER).join('').replace(/^\n+/, '');

/**
 * 토큰 CSS 첫 줄 헤더 — 프로젝트에 저장된 파일이 어느 발행본에서 왔는지 식별한다.
 * 2026-08-27 사고: 구 발행본(다크 블록 없음) 사본을 "이미 있으면 재사용" 규칙이 영원히 유지 →
 * AI 가 다크 CSS 54줄을 손으로 만들었다. 헤더의 hash 가 다르면 덮어쓰는 것이 재동기화 규약.
 */
export function tokensCssHeader(system: Pick<DesignSystemMeta, 'name' | 'version' | 'contentHash'>): string {
  return `/* @design-system ${system.name}@${system.version} hash:${system.contentHash.slice(0, 12)} — 발행본에서 생성. 수정 금지. 첫 줄 hash 가 다르면 새 CSS 로 덮어쓴다 */`;
}

export function buildTokensCss(tokens: DesignTokenMap, themes: Record<string, DesignTokenMap>, header?: string): string {
  const lines: string[] = header ? [header, ':root {'] : [':root {'];
  for (const [category, entries] of sortedCategories(tokens)) {
    for (const [key, value] of sortedEntries(entries)) {
      lines.push(`  --${category}-${key}: ${value};`);
    }
  }
  lines.push('}');
  const dark = themes.dark;
  if (dark && Object.keys(dark).length > 0) {
    lines.push('', '[data-theme="dark"] {');
    for (const [category, entries] of sortedCategories(dark)) {
      for (const [key, value] of sortedEntries(entries)) {
        lines.push(`  --${category}-${key}: ${value};`);
      }
    }
    lines.push('}');
  }
  return lines.join('\n') + '\n';
}

/** slug → PascalCase 파일명 (button-group → ButtonGroup) */
export function toPascalCase(slug: string): string {
  return slug
    .split('-')
    .filter(Boolean)
    .map((s) => s[0].toUpperCase() + s.slice(1))
    .join('');
}

